// One `### \`name\`` section of the harness catalog: a description paragraph,
// then the tool's parameters as a fenced ```json block, then its Source link.
//
// The file is machine-generated by the harness, so the walk is deliberately
// positional rather than clever: the description runs from the heading to the
// opening fence, and the JSON body runs from the opening fence to the next line
// that is exactly a closing fence. JSON is indented inside the fence, so a
// closing fence at column zero cannot appear inside the body.
const HEADING = /^### `(.+)`$/;
const OPEN = "```json";
const CLOSE = "```";

export default (Text) => {
	const Lines = Text.split("\n");
	const Tools = [];
	for (let Index = 0; Index < Lines.length; Index += 1) {
		const Heading = HEADING.exec(Lines[Index]);
		if (Heading === null) {
			continue;
		}
		const Name = Heading[1];
		let Open = Index + 1;
		while (Open < Lines.length && Lines[Open] !== OPEN) {
			Open += 1;
		}
		if (Open >= Lines.length) {
			throw new Error(`catalog: tool "${Name}" has no \`\`\`json block`);
		}
		const Description = Lines.slice(Index + 1, Open)
			.map((Line) => Line.trim())
			.filter((Line) => Line.length > 0)
			.join(" ");
		let Close = Open + 1;
		while (Close < Lines.length && Lines[Close] !== CLOSE) {
			Close += 1;
		}
		if (Close >= Lines.length) {
			throw new Error(`catalog: tool "${Name}" has an unterminated \`\`\`json block`);
		}
		let Schema;
		try {
			Schema = JSON.parse(Lines.slice(Open + 1, Close).join("\n"));
		} catch (Error) {
			throw new Error(`catalog: tool "${Name}" has invalid JSON: ${Error.message}`);
		}
		Tools.push({ name: Name, description: Description, schema: Schema });
		Index = Close;
	}
	if (Tools.length === 0) {
		throw new Error(
			"catalog: no `### \\`name\\`` tool sections found; is this a tool catalog?",
		);
	}
	return Tools;
};
